sys_script_include.script:
var ClaudeDiscoveryUtil = Class.create();
ClaudeDiscoveryUtil.prototype = {
    initialize: function() {
        this.constants = new x_agiro_ai_disc_cl.ClaudeDiscoveryConstants();
        this.apiClient = new x_agiro_ai_disc_cl.ClaudeApiClient();
        this._useOobImportSet = this._checkCrossScopeAccess();
    },

    // ========== Discovery Orchestrator ==========

    /**
     * Run full model discovery and load results into CMDB via sn_ai_disc staging.
     * @returns {{ success: boolean, modelsFound: number, message: string }}
     */
    discoverAll: function() {
        var startTime = new Date().getTime();
        var result = { success: false, modelsFound: 0, message: '' };

        try {
            // 1. Discover models
            var models = this.discoverModels();
            result.modelsFound = Object.keys(models).length;

            // 2. Discover tools (skills + connectors)
            var tools = this.discoverTools();
            var toolsFound = Object.keys(tools).length;

            if (result.modelsFound === 0 && toolsFound === 0) {
                result.message = 'No models or tools discovered';
                this._logRun('discovery', 'partial', result.message, 0, 0, 0, startTime);
                return result;
            }

            // 3. Build the sn_ai_disc result DTO
            var discoveryResult = this._buildResultDto(models, {}, tools, {});

            // 4. Load into staging and transform to CMDB
            this._loadToStaging(discoveryResult);

            result.success = true;
            result.message = 'Discovered ' + result.modelsFound + ' models, ' + toolsFound + ' tools';
            this._logRun('discovery', 'success', result.message, result.modelsFound, toolsFound, 0, startTime);

        } catch (e) {
            result.message = 'Discovery failed: ' + e.message;
            gs.error('[ClaudeDiscoveryUtil] ' + result.message);
            this._logRun('discovery', 'error', result.message, result.modelsFound, 0, 0, startTime);
        }

        return result;
    },

    // ========== Flow Designer Integration ==========

    /**
     * Discover models + tools and return result in the shape the OOB
     * "Discover Data Source" subflow and "Process AI Agents" action expect.
     * Called from Flow Designer, NOT from background scripts.
     * @returns {{ agents: Array, result: string, error_message: string }}
     */
    discoverForFlow: function() {
        var startTime = new Date().getTime();

        try {
            // Discover models
            var models = this.discoverModels();

            // Discover tools (skills + connectors from Enterprise Analytics)
            var tools = this.discoverTools();

            // Build the full result DTO
            var resultDto = this._buildResultDto(models, {}, tools, {});

            var modelCount = Object.keys(models).length;
            var toolCount = Object.keys(tools).length;

            this._logRun('discovery', 'success',
                'Flow discovery: ' + modelCount + ' models, ' + toolCount + ' tools',
                modelCount, toolCount, 0, startTime);

            return {
                agents: [],
                result: JSON.stringify(resultDto),
                error_message: ''
            };

        } catch (e) {
            var errMsg = 'Claude flow discovery failed: ' + e.message;
            gs.error('[ClaudeDiscoveryUtil] ' + errMsg);
            this._logRun('discovery', 'error', errMsg, 0, 0, 0, startTime);

            return {
                agents: [],
                result: '{}',
                error_message: errMsg
            };
        }
    },

    // ========== Model Discovery ==========

    /**
     * Discover Claude models from the hardcoded catalog, enriched with
     * actually-used models from the messages usage API.
     * @returns {object} Map of model id -> model DTO
     */
    discoverModels: function() {
        var models = {};

        // Start with the known model catalog
        var catalog = this.constants.MODEL_CATALOG;
        for (var i = 0; i < catalog.length; i++) {
            var cm = catalog[i];
            models[cm.id] = this._buildModelDto(cm.id, cm.name, cm.version, cm.description);
        }

        // Enrich with models seen in usage data (catches new models not in catalog)
        this._enrichModelsFromUsage(models);

        gs.info('[ClaudeDiscoveryUtil] Discovered ' + Object.keys(models).length + ' models');
        return models;
    },

    /**
     * Check messages usage API for models actually being used.
     * Any model found in usage that isn't in the catalog gets added.
     */
    _enrichModelsFromUsage: function(models) {
        try {
            var yesterday = this._getYesterdayISO();
            var response = this.apiClient.getMessagesUsage(yesterday, null, '1d');

            if (!response.success) {
                gs.warn('[ClaudeDiscoveryUtil] Could not enrich models from usage: ' + response.error);
                return;
            }

            var data = response.data;
            if (!data.data) return;

            for (var i = 0; i < data.data.length; i++) {
                var bucket = data.data[i];
                if (!bucket.results) continue;

                for (var j = 0; j < bucket.results.length; j++) {
                    var modelId = bucket.results[j].model;
                    if (modelId && !models[modelId]) {
                        models[modelId] = this._buildModelDto(
                            modelId,
                            this._formatModelName(modelId),
                            this._extractVersion(modelId),
                            'Discovered from usage data'
                        );
                        gs.info('[ClaudeDiscoveryUtil] Found new model from usage: ' + modelId);
                    }
                }
            }
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] Usage enrichment error: ' + e.message);
        }
    },

    // ========== Tool Discovery (Skills + Connectors) ==========

    /**
     * Discover tools from Enterprise Analytics API.
     * Skills and MCP connectors both map to sn_ent_ai_tool.
     * Requires Enterprise plan + analytics API key configured.
     * @returns {object} Map of tool id -> tool DTO
     */
    discoverTools: function() {
        var tools = {};

        var analyticsEnabled = gs.getProperty(this.constants.PROPERTY.ANALYTICS_ENABLED) === 'true';
        if (!analyticsEnabled) {
            gs.info('[ClaudeDiscoveryUtil] Analytics not enabled, skipping tool discovery');
            return tools;
        }

        var lagDays = 3;
        var date = this._getDateDaysAgo(lagDays);

        // Discover skills
        this._discoverSkills(tools, date);

        // Discover connectors
        this._discoverConnectors(tools, date);

        gs.info('[ClaudeDiscoveryUtil] Discovered ' + Object.keys(tools).length + ' tools (skills + connectors)');
        return tools;
    },

    /**
     * Fetch skills from Enterprise Analytics and add to tools map.
     */
    _discoverSkills: function(tools, date) {
        try {
            var page = null;
            var hasMore = true;

            while (hasMore) {
                var response = this.apiClient.getAnalyticsSkills(date, page);
                if (!response.success) {
                    gs.warn('[ClaudeDiscoveryUtil] Skills API failed: ' + response.error);
                    return;
                }

                var data = response.data;
                if (data.data && data.data.length > 0) {
                    for (var i = 0; i < data.data.length; i++) {
                        var skill = data.data[i];
                        var skillId = 'claude-skill-' + skill.skill_name;
                        tools[skillId] = this._buildToolDto(
                            skillId,
                            skill.skill_name,
                            'Claude Skill — ' + (skill.distinct_user_count || 0) + ' users',
                            true
                        );
                    }
                }

                hasMore = data.has_more === true;
                page = data.next_page || null;
            }
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] Skills discovery error: ' + e.message);
        }
    },

    /**
     * Fetch MCP connectors from Enterprise Analytics and add to tools map.
     */
    _discoverConnectors: function(tools, date) {
        try {
            var page = null;
            var hasMore = true;

            while (hasMore) {
                var response = this.apiClient.getAnalyticsConnectors(date, page);
                if (!response.success) {
                    gs.warn('[ClaudeDiscoveryUtil] Connectors API failed: ' + response.error);
                    return;
                }

                var data = response.data;
                if (data.data && data.data.length > 0) {
                    for (var i = 0; i < data.data.length; i++) {
                        var connector = data.data[i];
                        var connectorId = 'claude-connector-' + connector.connector_name;
                        tools[connectorId] = this._buildToolDto(
                            connectorId,
                            connector.connector_name,
                            'MCP Connector — ' + (connector.distinct_user_count || 0) + ' users',
                            true
                        );
                    }
                }

                hasMore = data.has_more === true;
                page = data.next_page || null;
            }
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] Connectors discovery error: ' + e.message);
        }
    },

    // ========== DTO Builders ==========

    /**
     * Build a model DTO matching the sn_ai_disc initializeModelsObject() shape.
     */
    _buildModelDto: function(id, name, version, description) {
        return {
            id: id,
            name: name,
            version: version || '',
            description: description || '',
            short_description: description || '',
            vendor: this.constants.VENDOR,
            manufacturer: this.constants.MANUFACTURER,
            install_status: String(this.constants.INSTALL_STATUS.DEPLOYED),
        };
    },

    /**
     * Build a tool DTO matching the sn_ai_disc initializeToolsObject() shape.
     * Maps to sn_ent_ai_tool in CMDB.
     */
    _buildToolDto: function(id, name, description, active) {
        return {
            id: id,
            name: name,
            description: description || '',
            vendor: this.constants.VENDOR,
            active: active !== false,
        };
    },

    /**
     * Build the top-level result DTO expected by sn_ai_disc.AiDiscoveryImportSetUtil.
     */
    _buildResultDto: function(models, agents, tools, prompts) {
        return {
            models: models,
            agents: agents || {},
            tools: tools || {},
            prompts: prompts || {},
            agent_subcomponent_m2m: [],
            additional_attributes: [],
        };
    },

    // ========== Staging / Import Set Loading ==========

    /**
     * Load discovery results into sn_ai_disc staging tables.
     * Tries OOB AiDiscoveryImportSetUtil first; falls back to direct staging writes.
     */
    _loadToStaging: function(result) {
        if (this._useOobImportSet) {
            this._loadViaOobImportSetUtil(result);
        } else if (this._hasStagingTables()) {
            this._loadDirectToStaging(result);
        } else {
            this._loadDirectToCmdb(result);
        }
    },

    /**
     * Use the OOB sn_ai_disc.AiDiscoveryImportSetUtil to load and transform.
     */
    _loadViaOobImportSetUtil: function(result) {
        try {
            var importSetUtil = new sn_ai_disc.AiDiscoveryImportSetUtil();
            var importResult = importSetUtil.transformAIAssetImportSet(result, this.constants.SOURCE_NAME);
            gs.info('[ClaudeDiscoveryUtil] OOB import set transform complete: ' + JSON.stringify(importResult));
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] OOB ImportSetUtil failed, falling back to direct load: ' + e.message);
            this._useOobImportSet = false;
            this._loadDirectToStaging(result);
        }
    },

    /**
     * Fallback: write directly to sn_ai_disc staging tables and trigger transform.
     */
    _loadDirectToStaging: function(result) {
        var stagingTable = 'sn_ai_disc_ai_model_asset_staging';

        // Create an import set record
        var importSetGr = new GlideRecord('sys_import_set');
        importSetGr.initialize();
        importSetGr.setValue('table_name', stagingTable);
        importSetGr.setValue('state', 'loading');
        importSetGr.setValue('mode', 'asynchronous');
        var importSetSysId = importSetGr.insert();

        if (!importSetSysId) {
            gs.error('[ClaudeDiscoveryUtil] Failed to create import set');
            return;
        }

        // Load model records into staging
        var modelCount = 0;
        for (var modelId in result.models) {
            if (!result.models.hasOwnProperty(modelId)) continue;
            var model = result.models[modelId];

            var stagingGr = new GlideRecord(stagingTable);
            stagingGr.initialize();
            stagingGr.setValue('u_id', model.id);
            stagingGr.setValue('u_name', model.name);
            stagingGr.setValue('u_version', model.version);
            stagingGr.setValue('u_description', model.description);
            stagingGr.setValue('u_short_description', model.short_description);
            stagingGr.setValue('u_vendor', model.vendor);
            stagingGr.setValue('u_manufacturer', model.manufacturer);
            stagingGr.setValue('u_install_status', model.install_status);
            stagingGr.setValue('sys_import_set', importSetSysId);
            stagingGr.insert();
            modelCount++;
        }

        // Mark import set as loaded
        importSetGr.get(importSetSysId);
        importSetGr.setValue('state', 'loaded');
        importSetGr.update();

        // Trigger transform
        var transformer = new GlideImportSetTransformer();
        transformer.transformAllMaps(importSetSysId);

        gs.info('[ClaudeDiscoveryUtil] Direct staging load complete: ' + modelCount + ' models, import set ' + importSetSysId);
    },

    /**
     * Write models and tools directly to CMDB tables, bypassing staging.
     * Used when sn_ai_disc v2 staging tables don't exist (v1.1.x instances).
     */
    _loadDirectToCmdb: function(result) {
        var modelCount = 0;
        var toolCount = 0;

        // Upsert models to alm_ai_model_digital_asset
        for (var modelId in result.models) {
            if (!result.models.hasOwnProperty(modelId)) continue;
            var model = result.models[modelId];

            var gr = new GlideRecord('alm_ai_model_digital_asset');
            gr.addQuery('name', model.name);
            gr.addQuery('vendor', model.vendor);
            gr.query();

            if (!gr.next()) {
                gr.initialize();
            }

            gr.setValue('name', model.name);
            gr.setValue('short_description', model.short_description || model.description);
            gr.setValue('description', model.description);
            gr.setValue('vendor', model.vendor);
            gr.setValue('manufacturer', model.manufacturer);
            gr.setValue('version', model.version);
            gr.setValue('install_status', model.install_status);
            gr.update() || gr.insert();
            modelCount++;
        }

        // Upsert tools to sn_ent_ai_tool
        for (var toolId in result.tools) {
            if (!result.tools.hasOwnProperty(toolId)) continue;
            var tool = result.tools[toolId];

            var tGr = new GlideRecord('sn_ent_ai_tool');
            tGr.addQuery('name', tool.name);
            tGr.addQuery('vendor', tool.vendor);
            tGr.query();

            if (!tGr.next()) {
                tGr.initialize();
            }

            tGr.setValue('name', tool.name);
            tGr.setValue('short_description', tool.description);
            tGr.setValue('vendor', tool.vendor);
            tGr.update() || tGr.insert();
            toolCount++;
        }

        gs.info('[ClaudeDiscoveryUtil] Direct CMDB write: ' + modelCount + ' models, ' + toolCount + ' tools');
    },

    /**
     * Check if sn_ai_disc v2 staging tables exist.
     */
    _hasStagingTables: function() {
        var gr = new GlideRecord('sn_ai_disc_ai_model_asset_staging');
        return gr.isValid();
    },

    // ========== Cross-Scope Access Check ==========

    /**
     * Check if we can access sn_ai_disc.AiDiscoveryImportSetUtil.
     * @returns {boolean}
     */
    _checkCrossScopeAccess: function() {
        try {
            if (typeof sn_ai_disc !== 'undefined' && sn_ai_disc.AiDiscoveryImportSetUtil) {
                return true;
            }
        } catch (e) {
            // Cross-scope access denied
        }
        gs.info('[ClaudeDiscoveryUtil] sn_ai_disc cross-scope access not available, will use direct staging');
        return false;
    },

    // ========== Run Log ==========

    /**
     * Write a record to the discovery run log.
     */
    _logRun: function(runType, status, message, modelsFound, toolsFound, usageRecords, startTime) {
        var duration = new Date().getTime() - startTime;

        var gr = new GlideRecord(this.constants.RUN_LOG_TABLE);
        gr.initialize();
        gr.setValue('x_agiro_ai_disc_cl_run_type', runType);
        gr.setValue('x_agiro_ai_disc_cl_status', status);
        gr.setValue('x_agiro_ai_disc_cl_message', (message || '').substring(0, 4000));
        gr.setValue('x_agiro_ai_disc_cl_models_found', modelsFound || 0);
        gr.setValue('x_agiro_ai_disc_cl_tools_found', toolsFound || 0);
        gr.setValue('x_agiro_ai_disc_cl_usage_records', usageRecords || 0);
        gr.setValue('x_agiro_ai_disc_cl_duration_ms', duration);
        gr.insert();
    },

    // ========== Utility ==========

    /**
     * Get yesterday's date as an ISO 8601 string (YYYY-MM-DDT00:00:00Z).
     */
    _getYesterdayISO: function() {
        var gdt = new GlideDateTime();
        gdt.addDaysUTC(-1);
        return gdt.getValue().substring(0, 10) + 'T00:00:00Z';
    },

    /**
     * Get a date N days ago as YYYY-MM-DD string.
     * @param {number} days - Number of days to go back
     * @returns {string} Date in YYYY-MM-DD format
     */
    _getDateDaysAgo: function(days) {
        var gdt = new GlideDateTime();
        gdt.addDaysUTC(-1 * days);
        return gdt.getValue().substring(0, 10);
    },

    /**
     * Format a model ID into a human-readable name.
     * e.g. 'claude-3-5-sonnet-20241022' -> 'Claude 3.5 Sonnet'
     */
    _formatModelName: function(modelId) {
        if (!modelId) return '';

        // Remove date suffix (e.g. -20241022)
        var name = modelId.replace(/-\d{8}$/, '');

        // Replace hyphens with spaces and capitalise
        var parts = name.split('-');
        for (var i = 0; i < parts.length; i++) {
            parts[i] = parts[i].charAt(0).toUpperCase() + parts[i].substring(1);
        }

        // Rejoin, fixing version numbers like "3 5" -> "3.5"
        var result = parts.join(' ');
        result = result.replace(/(\d) (\d)/g, '$1.$2');

        return result;
    },

    /**
     * Extract a version string from a model ID.
     * e.g. 'claude-3-5-sonnet-20241022' -> '3.5'
     */
    _extractVersion: function(modelId) {
        if (!modelId) return '';
        var match = modelId.match(/claude-(\d+(?:-\d+)?)/);
        if (match) {
            return match[1].replace('-', '.');
        }
        return '';
    },

    type: 'ClaudeDiscoveryUtil'
};
